Class Contador
  Define valor As Integer;

  Method Constructor()
    This.valor <- 0;
  EndMethod

  Method Incrementar()
    This.valor <- This.valor + 1;
  EndMethod

  Method Actual() As Integer
    Return This.valor;
  EndMethod
EndClass

Algorithm Contar
  Define pasos As Contador <- New Contador();
  pasos.Incrementar();
  pasos.Incrementar();
  Write pasos.Actual();
EndAlgorithm

Class Maquina
  Define stock, recaudado, precio As Integer;

  Method Constructor(latas As Integer)
    This.stock <- latas;
    This.recaudado <- 0;
    This.precio <- 3;
  EndMethod

  Method Vender() As Boolean
    If This.stock = 0 Then
      Return False;
    EndIf
    This.stock <- This.stock - 1;
    This.recaudado <- This.recaudado + This.precio;
    Return True;
  EndMethod

  Method Estado() As String
    Return toText(This.stock) + " latas, " + toText(This.recaudado) + " pesos";
  EndMethod
EndClass

Algorithm Kiosco
  Define primera As Maquina <- New Maquina(10);
  Define segunda As Maquina <- New Maquina(10);
  Write primera.Vender(), " ", primera.Vender(), " ", segunda.Vender();
  Write "Máquina 1: ", primera.Estado();
  Write "Máquina 2: ", segunda.Estado();
EndAlgorithm

Class Maquina
  Define stock, recaudado, precio As Integer;

  Method Constructor(latas As Integer)
    This.stock <- latas;
    This.recaudado <- 0;
    This.precio <- 3;
  EndMethod

  Method Vender() As Boolean
    If This.stock = 0 Then
      Return False;
    EndIf
    This.stock <- This.stock - 1;
    This.recaudado <- This.recaudado + This.precio;
    Return True;
  EndMethod
EndClass

Algorithm Vacia
  Define maquina As Maquina <- New Maquina(0);
  Write maquina.Vender(), " ", maquina.stock, " ", maquina.recaudado;
EndAlgorithm
